def validate_forward_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != FORWARD_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    # ports/age 与新式 forward 契约一致，复用其全量校验
    ports, age = validate_forward_config_v2(
        {"ports": config["ports"], "age": config["age"]}
    )
    return ports, age, max_frame


def validate_forward_check_frames(frames, ports):
    if not isinstance(frames, list):
        raise InvalidInput("frames must be a list")
    base = []
    extras = []
    for frame in frames:
        if (
            not isinstance(frame, dict)
            or frozenset(frame) != FORWARD_CHECK_FRAME_KEYS
        ):
            raise InvalidInput("bad frame")
        length = frame["length"]
        fcs = frame["fcs"]
        alignment = frame["alignment"]
        if not _is_int(length) or length < 0:
            raise InvalidInput("bad length")
        if not isinstance(fcs, bool):
            raise InvalidInput("bad fcs")
        if not isinstance(alignment, bool):
            raise InvalidInput("bad alignment")
        # t/port/src/dst/vlan 与新式帧契约一致，复用其全量校验
        base.append(
            {key: frame[key] for key in ("t", "port", "src", "dst", "vlan")}
        )
        extras.append((length, fcs, alignment))
    checked = validate_frames_v2(base, ports)
    return [
        (t, port, src, dst, vlan, length, fcs, alignment)
        for (t, port, src, dst, vlan), (length, fcs, alignment) in zip(
            checked, extras
        )
    ]


def forward_check(frames, ports, age, max_frame):
    by_name = {port["name"]: port for port in ports}
    fdb = {}  # (vlan, mac) -> [port, seen]
    port_stats = {
        port["name"]: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []
    for t, port_name, src, dst, tag, length, fcs, alignment in frames:
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1
        if cls != "good":  # 非 good 丢弃且不学习、不转发、不计 VLAN
            port_stats[port_name]["drop"] += 1
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            continue
        if tag is None:
            vlan = ingress["pvid"]
            rejected = False
        else:
            vlan = tag
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # 拒绝帧丢弃且不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            continue
        vlan_stats[vlan]["rx"] += 1
        egress = []
        action = "drop"
        if ingress["up"]:
            fdb[(vlan, src)] = [port_name, t]
            hit = None if dst == BROADCAST_MAC else fdb.get((vlan, dst))
            if hit is not None and hit[0] != port_name:
                target = by_name[hit[0]]
                if target["up"] and vlan in target["allowed"]:
                    egress = [hit[0]]
                    action = "unicast"
            elif hit is None:
                egress = [
                    port["name"]
                    for port in ports
                    if vlan in port["allowed"]
                    and port["up"]
                    and port["name"] != port_name
                ]
                if egress:
                    action = "flood"
        out_ports = []
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[vlan]["tx"] += 1
            out_ports.append(
                {
                    "name": name,
                    "vlan": None if vlan in by_name[name]["untagged"] else vlan,
                }
            )
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        results.append(
            {"t": t, "class": cls, "action": action, "ports": out_ports}
        )
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
                "good": port_stats[port["name"]]["good"],
                "runt": port_stats[port["name"]]["runt"],
                "giant": port_stats[port["name"]]["giant"],
                "alignment": port_stats[port["name"]]["alignment"],
                "bad_fcs": port_stats[port["name"]]["bad_fcs"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
    }


def forward_check_work(frames, ports, age, max_frame, limit):
    """forward-check/forward-decode 的工作量预演：独立空 FDB，无副作用。

    P 为配置端口数；逐帧先老化动态项，以老化前动态 FDB 表项数 K 计
    K+P+1（坏帧、VLAN 准入拒绝、down 口均计费），等于上限合法；随后
    仅 good（非 runt/giant/alignment/bad_fcs）且通过 VLAN 准入且入端口
    up 时学习、刷新或迁移源 MAC。首次超过即抛 ForwardWorkLimit。
    """
    by_name = {port["name"]: port for port in ports}
    width = len(ports) + 1
    fdb = {}  # (vlan, mac) -> [port, seen]
    work = 0
    for t, port_name, src, dst, tag, length, fcs, alignment in frames:
        work += len(fdb) + width
        if work > limit:
            raise ForwardWorkLimit
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        # 坏帧（含 forward-decode 恒真的 alignment）不计 VLAN、不学习
        if (
            length < FRAME_CHECK_RUNT_LENGTH
            or length > max_frame
            or not alignment
            or not fcs
        ):
            continue
        ingress = by_name[port_name]
        if tag is None:
            vlan = ingress["pvid"]
            rejected = False
        else:
            vlan = tag
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if not rejected and ingress["up"]:
            fdb[(vlan, src)] = [port_name, t]


def validate_forward_decode_frames(frames, ports):
    # 帧外壳契约（t/port/data、单层 8100、双标签拒绝）与 frame-decode
    # 一致，复用其全量校验；ports 为新式端口字典，取其名字集合
    checked = validate_frame_decode_frames(
        frames, [port["name"] for port in ports]
    )
    for _, _, raw in checked:
        dst = raw[0:6]
        src = raw[6:12]
        if not any(dst):  # 目的 MAC 全零非法
            raise InvalidInput("bad dst")
        if not any(src) or src[0] & 1:  # 源 MAC 须为非零单播
            raise InvalidInput("bad src")
    return checked


def _decode_raw_frames(frames):
    """按 frame-decode 规则解析原始帧为 forward_check 的八元组帧序。

    无对齐概念，alignment 恒真，分类退化为 runt/giant/bad_fcs/good。
    """
    checked = []
    for t, port, raw in frames:
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            vlan = tci & 0x0FFF
        else:
            vlan = None
        fcs = raw[-4:] == (zlib.crc32(raw[:-4]) & 0xFFFFFFFF).to_bytes(
            4, "little"
        )
        checked.append((t, port, src, dst, vlan, len(raw), fcs, True))
    return checked


def forward_decode(frames, ports, age, max_frame):
    # 按 frame-decode 规则解析原始帧，再接入新式 forward（forward_check）
    return forward_check(_decode_raw_frames(frames), ports, age, max_frame)


